  import { Project, Task, TaskStatus, User, Repository } from '../domain/models';

  export class TaskService {
    constructor(private repository: Repository) {}

    createProject(projectId: string, name: string): Project {
      const project: Project = { id: projectId, name, tasks: [] };
      this.repository.projects.set(projectId, project);
      return project;
    }

    createUser(userId: string, name: string): User {
      const user: User = { id: userId, name };
      this.repository.users.set(userId, user);
      return user;
    }

    addTask(
      projectId: string,
      taskId: string,
      title: string,
      description: string,
      dueDate?: Date
    ): Task {
      const project = this.repository.projects.get(projectId);
      if (!project) {
        throw new Error(`Project ${projectId} not found`);
      }

      const task: Task = {
        id: taskId,
        title,
        description,
        status: 'todo',
        dueDate,
        projectId,
      };
      project.tasks.push(task);
      return task;
    }

    assignTask(projectId: string, taskId: string, assigneeId: string): Task {
      const project = this.repository.projects.get(projectId);
      if (!project) {
        throw new Error(`Project ${projectId} not found`);
      }

      const task = project.tasks.find((t) => t.id === taskId);
      if (!task) {
        throw new Error(`Task ${taskId} not found`);
      }

      const user = this.repository.users.get(assigneeId);
      if (!user) {
        throw new Error(`User ${assigneeId} not found`);
      }

      task.assigneeId = assigneeId;
      return task;
    }

    markTaskDone(projectId: string, taskId: string): Task {
      const project = this.repository.projects.get(projectId);
      if (!project) {
        throw new Error(`Project ${projectId} not found`);
      }

      const task = project.tasks.find((t) => t.id === taskId);
      if (!task) {
        throw new Error(`Task ${taskId} not found`);
      }

      if (task.status === 'done') {
        throw new Error(`Task ${taskId} is already done`);
      }

      task.status = 'done';
      return task;
    }

    listTasks(
      projectId: string,
      filters?: { status?: TaskStatus; assigneeId?: string }
    ): Task[] {
      const project = this.repository.projects.get(projectId);
      if (!project) {
        throw new Error(`Project ${projectId} not found`);
      }

      let tasks = project.tasks;

      if (filters?.status) {
        tasks = tasks.filter((t) => t.status === filters.status);
      }

      if (filters?.assigneeId) {
        tasks = tasks.filter((t) => t.assigneeId === filters.assigneeId);
      }

      return tasks;
    }

    getProject(projectId: string): Project {
      const project = this.repository.projects.get(projectId);
      if (!project) {
        throw new Error(`Project ${projectId} not found`);
      }
      return project;
    }
  }

